@import url('https://fonts.googleapis.com/css2?family=Open+Sans:wght@300;400;600;700&display=swap');

.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #247cff;
  --vt-on-accent: #FFFFFF;
  --vt-accent-ink: #247cff;
  --vt-accent-on-deep: #247cff;
  --vt-line: #eaeaea;

  font-family: 'Open Sans', sans-serif;
  background: var(--vt-surface);
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  line-height: 1.5;
  padding-top: 94px;
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

/* NAVIGATION */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  z-index: 1000;
  padding: 20px 0;
}

.navIn {
  max-width: 1140px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 15px;
}

.logo {
  text-decoration: none;
  color: var(--vt-accent);
  font-size: 24px;
  font-weight: 700;
  text-align: center;
  margin: 0 30px;
}

.navLinks {
  display: flex;
  gap: 1.5rem;
}

.navLinks a {
  color: var(--vt-ink-soft);
  font-weight: 600;
  font-size: 16px;
  text-decoration: none;
  padding: 15px 0;
}

.navLinks a:hover {
  color: var(--vt-ink);
}

/* HERO */
.hero {
  position: relative;
  overflow: hidden;
  height: 580px;
  padding-top: 0;
}

@media (min-width: 1600px) {
  .hero {
    height: 740px;
  }
}

.heroTrack {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  height: 100%;
  -webkit-overflow-scrolling: touch;
}

.heroSlide {
  flex: 0 0 100%;
  scroll-snap-align: start;
  margin: 0;
}

.heroSlide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.heroText {
  background: var(--vt-surface);
  position: absolute;
  z-index: 2;
  bottom: 0;
  right: 0;
  padding: 1.5rem 2.5rem;
  width: 50%;
}

.heroText h1 {
  font-size: 48px;
  font-weight: 700;
  color: var(--vt-ink);
  margin-bottom: 0.5rem;
}

.heroText p {
  color: var(--vt-ink-soft);
  font-size: 18px;
  margin-bottom: 1rem;
}

.heroLinks {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

.customLink {
  display: inline-block;
  text-decoration: none;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  position: relative;
  overflow: hidden;
  text-transform: uppercase;
  transition: all 0.3s;
}

.customLink::before {
  content: attr(data-hover);
  background-color: var(--vt-line);
  color: var(--vt-accent);
  position: absolute;
  top: 100%;
  bottom: 0;
  left: 0;
  right: 0;
  text-align: center;
  transition: top 300ms cubic-bezier(0.19, 1, 0.56, 1);
}

.customLink:hover::before {
  top: 0;
}

.contactPhone {
  font-weight: 600;
  color: var(--vt-ink-soft);
  margin: 0;
}

/* SECTIONS */
.sectionPadding {
  padding-top: 7rem;
  padding-bottom: 7rem;
}

@media (max-width: 991px) {
  .sectionPadding {
    padding-top: 5rem;
    padding-bottom: 5rem;
  }
}

.container {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
}

.aboutRow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
}

.aboutText {
  flex: 0 0 50%;
  max-width: 50%;
}

@media (max-width: 991px) {
  .aboutText {
    flex: 0 0 100%;
    max-width: 100%;
  }
}

.aboutText h2 {
  color: var(--vt-ink);
  font-size: 36px;
  font-weight: 700;
  margin-bottom: 1rem;
}

.aboutText p {
  color: var(--vt-ink-soft);
  font-size: 18px;
  margin-bottom: 1rem;
}

/* GALLERY */
.gallery {
  background: var(--vt-surface-2);
}

.galleryRow {
  display: flex;
  flex-wrap: wrap;
  margin: 0;
}

.galleryItem {
  flex: 0 0 50%;
  max-width: 50%;
  padding: 0;
  margin: 0;
}

.galleryItem img {
  width: 100%;
  height: auto;
  display: block;
}

.galleryItem:first-child {
  padding-right: 0;
}

.galleryItem:last-child {
  padding-left: 0;
}

/* TIMELINE */
.timeline {
  position: relative;
  padding: 0;
  margin-top: 3rem;
}

.timeline::before {
  content: "";
  position: absolute;
  top: 37px;
  left: 50%;
  width: 0;
  border-left: 1px solid var(--vt-line);
  height: 85%;
  transform: translateX(-50%);
  z-index: 1;
}

.timelineRow {
  display: flex;
  align-items: flex-start;
  justify-content: space-around;
  position: relative;
  margin-bottom: 3rem;
}

.timelineRowOdd {
  flex-direction: row;
}

.timelineRowEven {
  flex-direction: row-reverse;
}

.timelineContent {
  flex: 0 0 41.6667%;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  border-radius: 0 0 0.25rem 0.25rem;
  position: relative;
  padding: 0;
}

.timelineContent h3 {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  border-radius: 0.25rem 0.25rem 0 0;
  margin: 0;
  font-weight: 600;
}

.timelineContent p {
  color: var(--vt-ink-soft);
  padding: 10px 30px;
  margin: 0;
}

.timelineRowOdd .timelineContent h3,
.timelineRowOdd .timelineContent p {
  text-align: right;
}

.timelineRowEven .timelineContent h3,
.timelineRowEven .timelineContent p {
  text-align: left;
}

.timelineRowOdd .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translateY(-50%);
  border-left: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineRowEven .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translateY(-50%);
  border-right: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineIconWrap {
  position: relative;
  z-index: 2;
  flex: 0 0 8.3333%;
  text-align: center;
  padding-top: 0;
}

.timelineIconWrap::before {
  content: "";
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--vt-surface);
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  z-index: 1;
}

.timelineIcon {
  position: relative;
  z-index: 2;
  font-size: 32px;
  color: var(--vt-accent);
  line-height: 80px;
  display: block;
}

.timelineDate {
  flex: 0 0 41.6667%;
  padding-top: 37px;
}

.timelineRowOdd .timelineDate {
  text-align: left;
}

.timelineRowEven .timelineDate {
  text-align: right;
}

.timelineDate time {
  color: var(--vt-ink-soft);
  font-size: 16px;
}

/* FOOTER */
.footer {
  background: var(--vt-surface-2);
  padding-top: 5rem;
  padding-bottom: 5rem;
}

.footerRow {
  display: flex;
  flex-wrap: wrap;
  margin: -15px;
}

.footerCol {
  flex: 1 0 300px;
  padding: 15px;
}

.footerCol h5 {
  color: var(--vt-ink);
  font-size: 20px;
  margin-bottom: 1rem;
}

.footerCol p {
  color: var(--vt-ink-soft);
  font-size: 16px;
}

.socialLinks {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  gap: 15px;
}

.socialLinks a {
  color: var(--vt-ink-soft);
  text-decoration: none;
  font-size: 18px;
}

.socialLinks a:hover {
  color: var(--vt-accent);
}

.copyright {
  margin-top: 2rem;
  text-align: left;
}

.copyright p {
  font-size: 16px;
  color: var(--vt-ink-soft);
}

/* RESPONSIVE */
@media (max-width: 767px) {
  .navIn {
    flex-direction: column;
    align-items: flex-start;
  }

  .navLinks {
    flex-wrap: wrap;
    gap: 0.5rem;
    margin-top: 10px;
  }

  .navLinks a {
    padding: 5px 10px;
  }

  .hero {
    height: auto;
  }

  .heroText {
    position: relative;
    bottom: auto;
    right: auto;
    width: auto;
    margin-bottom: 0;
    padding: 2rem;
  }

  .heroTrack {
    height: 300px;
  }

  .timeline::before {
    top: 60px;
    left: 33px;
    height: 90%;
    transform: translateX(-50%);
  }

  .timelineRow {
    flex-direction: row;
    justify-content: flex-start;
    padding-left: 70px;
  }

  .timelineContent {
    flex: 0 0 100%;
    margin-left: 0;
  }

  .timelineIconWrap {
    position: absolute;
    left: 0;
    top: 60px;
    flex: none;
    width: 70px;
  }

  .timelineIconWrap::before {
    width: 70px;
    height: 70px;
  }

  .timelineIcon {
    line-height: 70px;
    font-size: 28px;
  }

  .timelineDate {
    flex: 0 0 100%;
    padding-top: 0;
    text-align: left !important;
  }

  .timelineRowOdd .timelineContent h3,
  .timelineRowOdd .timelineContent p {
    text-align: left;
  }

  .timelineRowOdd .timelineContent h3::after,
  .timelineRowEven .timelineContent h3::after {
    display: none;
  }
}

@media (max-width: 575px) {
  .timeline::before {
    left: 57px;
  }

  .timelineRow {
    padding-left: 90px;
  }

  .timelineIconWrap {
    left: -10px;
  }

  .timelineIconWrap::before {
    width: 70px;
    height: 70px;
  }
}
